let data=null;
let direction='outbound';
let routeId='local';
const routes={local:{label:'吉安 → 瑞穗',from:'吉安',to:'瑞穗',weather:['吉安鄉','瑞穗鄉','花蓮市']},'hualien-taipei':{label:'花蓮 → 臺北',from:'花蓮',to:'臺北',weather:['花蓮市']},'hualien-luodong':{label:'花蓮 → 羅東',from:'花蓮',to:'羅東',weather:['花蓮市']}};
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stationName=s=>String(s??'').replace(/^\d+-/,'');
const taipei=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const stamp=t=>t?new Date(t).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}):'尚無資料';
const age=t=>t?(Date.now()-Date.parse(t))/60000:Infinity;
const statusText=t=>t?.lastReported?`官方動態：${t.lastReported.name} ${t.lastReported.status}`:t?.status?`官方動態：${t.status}`:t?.statusCheckedAt?'官方已查詢：暫無準誤點回報':'尚未取得官方動態';
const statusTone=t=>{const value=String(t?.status||t?.lastReported?.status||'').trim();if(!value)return t?.statusCheckedAt?'checked':'unknown';return /誤點|停駛|取消/.test(value)?'bad':/準點|正常/.test(value)?'good':'checked'};
const officialPosition=t=>t?.lastReported&&/到站|發車|運轉/.test(t.lastReported.status||'')?t.lastReported:null;
const parseMinutes=s=>{const m=String(s||'').match(/(\d{2}):(\d{2})/);return m?Number(m[1])*60+Number(m[2]):9999};
const normalizeStation=s=>String(s||'').trim().replaceAll('台北','臺北').replace(/[市縣鄉鎮區]$/,'');

function active(){const date=$('date').value,source=data?.days?.[date],profile=routes[routeId];let route=source?.routes?.find(r=>r.id===routeId&&r.direction===direction);let rows=route?.trains||[];if(routeId==='local')rows=source?.trains?.filter(t=>t.direction===direction)||[];return {date,source,profile,route,rows};}
function setRouteByInputs(){const from=normalizeStation($('from').value),to=normalizeStation($('to').value);let match=Object.entries(routes).find(([,r])=>normalizeStation(r.from)===from&&normalizeStation(r.to)===to);if(match){routeId=match[0];direction='outbound'}else{match=Object.entries(routes).find(([,r])=>normalizeStation(r.to)===from&&normalizeStation(r.from)===to);if(match){routeId=match[0];direction='inbound'}}if(!match)routeId='custom';for(const x of ['outbound','inbound'])$(x).setAttribute('aria-pressed',String(x===direction));}
function routeButtons(){const box=$('saved-routes');box.innerHTML=Object.entries(routes).map(([id,r])=>`<button type="button" data-route="${id}">${r.from} → ${r.to}</button>`).join('');for(const b of box.querySelectorAll('button'))b.onclick=()=>{routeId=b.dataset.route;$('from').value=routes[routeId].from;$('to').value=routes[routeId].to;render()};}
function statusMarkup(t,stale=false){const tone=stale?'unknown':statusTone(t),text=stale?'動態資料已過期':statusText(t),label={bad:'誤點提醒',good:'官方正常',checked:'官方已查',unknown:'等待資料'}[tone];return `<div class="status-line ${tone}"><span class="status-chip"><i></i>${label}</span><strong>${esc(text)}</strong>${t?.statusCheckedAt?`<small>動態取回 ${esc(stamp(t.statusCheckedAt))}</small>`:''}</div>`;}
function trainUrl(no,date){return `https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/querybytrainno?rideDate=${date.replaceAll('-','/')}&trainNo=${encodeURIComponent(no)}`;}
function milestonesMarkup(t,date){const marks=t?.milestones||[];if(!marks.length)return '';const today=date===taipei(new Date());const nowParts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const minutes=Number(nowParts.find(x=>x.type==='hour')?.value||0)*60+Number(nowParts.find(x=>x.type==='minute')?.value||0);const inMotion=today&&parseMinutes(t.departure)<=minutes&&minutes<parseMinutes(t.arrival);const official=officialPosition(t);let current=today&&official?.name?marks.findIndex(m=>m.name===official.name):-1;let estimated=false;if(current<0&&inMotion){current=marks.reduce((last,m,i)=>parseMinutes(m.departure||m.arrival)<=minutes?i:last,-1);estimated=current>=0}const location=today?(official?.name?`官方定位：${official.name}`:inMotion?'時刻推估位置（非官方定位）':minutes<parseMinutes(t.departure)?'尚未出發':'本日已到站'):'本日行程站點';return `<div class="route-journey"><div class="route-journey-head"><span>${esc(location)}</span><span>左右滑動看完整站點</span></div><div class="route-journey-body"><button class="route-nav" type="button" data-route-scroll="prev" aria-label="查看前面的站">‹</button><div class="route-scroll" tabindex="0" aria-label="${esc(t.type||'列車')} ${esc(t.no||'')} 完整停靠站">${marks.map((m,i)=>`<span class="route-stop ${i===current?'train-here':''} ${estimated&&i===current?'estimated-position':''} ${m.status?'has-status':''}"><i></i>${i===current?`<em class="${estimated?'estimated':''}" aria-label="${estimated?'依時刻推估列車位置':'官方列車位置'}">🚆</em>`:''}<b>${esc(m.name)}</b><small>${esc(m.departure||m.arrival||'—')}</small>${m.status?`<u>${esc(m.status)}</u>`:''}</span>`).join('')}</div><button class="route-nav" type="button" data-route-scroll="next" aria-label="查看後面的站">›</button></div></div>`;}
function enableRouteScrollers(){document.querySelectorAll('[data-route-scroll]').forEach(button=>button.onclick=()=>{const scroller=button.parentElement.querySelector('.route-scroll');scroller.scrollBy({left:(button.dataset.routeScroll==='next'?1:-1)*Math.max(220,scroller.clientWidth*.72),behavior:'smooth'})});document.querySelectorAll('.route-scroll').forEach(scroller=>{let startX=0,startY=0,startLeft=0;scroller.addEventListener('touchstart',event=>{const touch=event.touches[0];startX=touch.clientX;startY=touch.clientY;startLeft=scroller.scrollLeft},{passive:true});scroller.addEventListener('touchmove',event=>{const touch=event.touches[0],dx=touch.clientX-startX,dy=touch.clientY-startY;if(Math.abs(dx)>Math.abs(dy)){event.preventDefault();scroller.scrollLeft=startLeft-dx}},{passive:false});const here=scroller.querySelector('.train-here');if(here)requestAnimationFrame(()=>here.scrollIntoView({block:'nearest',inline:'center'}))})}
function render(){if(!data)return;const {date,source,profile,route,rows}=active();const stale=age(route?.checkedAt||source?.checkedAt)>15;const custom=routeId==='custom';const origin=custom?$('from').value:(direction==='outbound'?profile.from:profile.to),destination=custom?$('to').value:(direction==='outbound'?profile.to:profile.from);
  if(!custom){$('from').value=origin;$('to').value=destination}const corridorTitle=routeId==='hualien-taipei'?(direction==='outbound'?'臺東・花蓮 → 臺北':'臺北 → 花蓮・臺東'):routeId==='hualien-luodong'?(direction==='outbound'?'花蓮 → 宜蘭・羅東':'羅東・宜蘭 → 花蓮'):null;$('journey-title').textContent=custom?`${$('from').value||'起點'} → ${$('to').value||'終點'}`:(corridorTitle||`${origin} → ${destination}`);
  $('freshness').textContent=source?`列車資料取回：${stamp(route?.checkedAt||source.checkedAt)}${stale?' ｜已過期，請以台鐵公告為準。':' ｜每 10 分鐘向台鐵更新；頁面每分鐘讀取一次。'}`:'這個日期尚未取得資料，請換日期或等待下一輪自動更新。';
  $('rail-status').textContent=(data.rail?.text||'尚未取得路線公告')+' · '+stamp(data.rail?.checkedAt);
  $('mode-note').textContent=custom?'已收到你的路線：目前尚未建立這條路線的自動擷取設定；請先使用三條已啟用路線，或把這條路線告訴我加入。':'官方動態顯示準誤點；未提供精確位置時，小火車會以灰色時刻推估標示。';
  const nowParts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const nowMinutes=Number(nowParts.find(x=>x.type==='hour')?.value||0)*60+Number(nowParts.find(x=>x.type==='minute')?.value||0);const isToday=date===taipei(new Date());const runningRows=isToday?rows.filter(t=>parseMinutes(t.departure)<=nowMinutes&&nowMinutes<parseMinutes(t.arrival)):[];const running=runningRows[0]||null;const upcoming=rows.find(t=>parseMinutes(t.departure)>nowMinutes)||null;const focus=running||upcoming||null;const companion=runningRows.slice(1)[0]||upcoming;
  const phase=running?'依時刻判定・行駛中':'下一班';$('focus-title').textContent=running?'主看這一班':'下一班列車';
  $('next-train').innerHTML=focus?`<div class="focus-label ${running?'running':''}">${phase}</div><div class="next-time">${esc(focus.departure)}</div><div class="next-name">${esc(focus.type)} <b>${esc(focus.no)}</b></div>${statusMarkup(focus,stale)}<p>${esc(stationName(focus.from))} 出發 → ${esc(stationName(focus.to))} 抵達 ${esc(focus.arrival)}</p><a href="${trainUrl(focus.no,date)}" target="_blank" rel="noopener">查看官方逐站動態 ↗</a>`:'<div class="no-data">這個日期尚未有可用班次。<br><small>路線資料會由下一輪官方查詢補上。</small></div>';
  $('upcoming-train').innerHTML=running&&companion?`<div class="upcoming-label">${runningRows.length>1?'同時行駛':'接著一班'}</div><b>${esc(companion.departure)}　${esc(companion.type)} ${esc(companion.no)}</b><span>抵達 ${esc(companion.arrival)}</span>${statusMarkup(companion,stale)}`:'';
  const focusText=running?(officialPosition(focus)?`官方定位：${officialPosition(focus).name}`:focus.lastReported?`官方動態：${focus.lastReported.name} ${focus.lastReported.status}`:'依時刻行駛中'):(focus.lastReported?`官方動態：${focus.lastReported.name} ${focus.lastReported.status}`:focus.status||'下一班');$('hero-train').innerHTML=focus?`<div class="hero-line"><span class="hero-type">${esc(focus.type)} ${esc(focus.no)}</span><span class="hero-status ${statusTone(focus)}">${esc(focusText)}</span></div><div class="hero-times"><strong>${esc(focus.departure)}</strong><span class="hero-arrow">→</span><strong>${esc(focus.arrival)}</strong></div><div class="hero-caption"><span>${esc(stationName(focus.from))}</span><span>${esc(stationName(focus.to))}</span></div>${statusMarkup(focus,stale)}${milestonesMarkup(focus,date)}`:'<div class="no-data">尚無這條路線的本日資料。</div>';
  $('timeline').innerHTML=focus?`<div class="journey-key"><span><i class="key-train">🚆</i> 小火車＝行駛位置；灰色代表時刻推估</span><span class="key-bad"><i></i> 陶土紅＝誤點</span><span class="key-good"><i></i> 苔綠＝官方正常</span></div>`:'<div class="timeline-empty">選擇其他日期，查看完整行程。</div>';
  const alternatives=focus?rows.filter(t=>t.no!==focus.no):rows;$('alternatives').hidden=!alternatives.length;$('trains').innerHTML=alternatives.map(t=>`<article class="train-card"><div class="train-card-top"><span>${esc(t.type)}</span><b>${esc(t.no)}</b><em>其他班次</em></div><div class="train-card-time"><strong>${esc(t.departure)}</strong><span>→</span><strong>${esc(t.arrival)}</strong></div><div class="train-card-stations"><span>${esc(stationName(t.from))} 出發</span><span>${esc(stationName(t.to))} 抵達</span></div>${statusMarkup(t,stale)}<a href="${trainUrl(t.no,date)}" target="_blank" rel="noopener">查看官方逐站動態 ↗</a></article>`).join('');
  const weatherNames=profile?.weather||['花蓮市'];$('weather').innerHTML=weatherNames.map((name,i)=>{const w=data.weather?.[name],hours=w?.hours?.filter(h=>h.date===date)||[],h=hours[0];return `<article class="weather-stop ${i===0?'visible':''}"><div class="weather-stop-index">0${i+1}</div><div><b>${esc(name)}</b><small>${w?'預報取回 '+stamp(w.checkedAt):'沿線預報下一輪擷取'}</small></div><div class="weather-main">${h?`<strong>${esc(h.temperature)}°</strong><span>${esc(h.description||'天氣狀況未提供')}<br>雨 ${esc(h.rain||'未提供')} · 風 ${esc(h.wind||'未提供')}</span>`:'<span>目前尚無此段預報</span>'}</div></article>`}).join('');
  $('collection-info').textContent=`另有 ${alternatives.length} 班 · ${stale?'動態已過期':'官方資料已取回 '+stamp(route?.checkedAt||source?.checkedAt)}`;enableRouteScrollers();
}
async function refresh(){try{const r=await fetch(`data.json?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw Error();data=await r.json();if(!$('date').dataset.chosen){const now=new Date(),today=taipei(now),tomorrow=taipei(new Date(+now+86400000));const h=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',hour12:false}).format(now));$('date').value=h>=20&&data.days?.[tomorrow]?tomorrow:data.days?.[today]?today:tomorrow;direction=h>=12&&h<20?'inbound':'outbound';}render()}catch{$('freshness').textContent='資料讀取失敗，請稍後再試。'}}
routeButtons();$('date').value=taipei(new Date());$('trip-form').onsubmit=e=>{e.preventDefault();setRouteByInputs();$('date').dataset.chosen='true';render()};$('swap').onclick=()=>{const a=$('from').value;$('from').value=$('to').value;$('to').value=a;setRouteByInputs();render()};for(const id of ['outbound','inbound'])$(id).onclick=()=>{direction=id;for(const x of ['outbound','inbound'])$(x).setAttribute('aria-pressed',String(x===id));render()};$('date').onchange=()=>{$('date').dataset.chosen='true';render()};setInterval(()=>{$('clock').textContent=stamp(new Date().toISOString())},1000);setInterval(()=>{if(!document.hidden)refresh()},60000);refresh();
